insert into products (id, slug, sku, name, category, price, compare_at_price, description, details, material, status, is_featured, show_size_guide, sort_order) values
  ('9726a7b0-9ace-498f-ad86-455398273f8f', 'a-piece-of-bali', 'SOS-APP-001', 'A Piece of Bali', 'apparel', 220000, 250000, 'Kaos edisi Tennis Escape Bali — bunga kamboja ala lapangan tenis di punggung, dibuat untuk member yang ikut sesi di Kintamani. Enak dipakai main, lebih enak lagi dipakai setelahnya.', array['Cotton combed 24s, 220 gsm — tebal tapi tetap adem untuk main pagi.', 'Sablon plastisol di bagian belakang, tahan dicuci berulang.', 'Jahitan rantai di bahu & leher supaya tidak melar.']::text[], '100% cotton combed 24s, 220 gsm. Cuci dengan air dingin, jangan disetrika langsung di atas sablon.', 'active', true, true, 0),
  ('c4254ae7-2753-48f0-a4ba-7d72759ff16d', 'a-piece-of-the-really', 'SOS-APP-002', 'A Piece of The Really', 'apparel', 220000, 250000, 'Kaos “Beyond the Court” dengan sablon bunga tangan di punggung. Washed charcoal yang makin bagus tiap kali dicuci — buat main, nongkrong, sampai jalan-jalan.', array['Cotton combed 24s, 220 gsm — tebal tapi tetap adem untuk main pagi.', 'Sablon plastisol di bagian belakang, tahan dicuci berulang.', 'Jahitan rantai di bahu & leher supaya tidak melar.']::text[], '100% cotton combed 24s, 220 gsm, proses acid wash. Warna bisa sedikit berbeda tiap potong.', 'active', true, true, 1),
  ('52509a6b-fc20-4e87-af93-24d96c28b79d', 'pro-racket-series', 'SOS-RCK-004', 'Pro Racket Series', 'racket', 800000, null, 'Raket kontrol untuk pemain intermediate–advanced. Frame kaku, feel solid saat volley di net.', array['Head size 100 sq in — sweet spot luas, cocok untuk rally panjang.', 'Berat tanpa senar ±300 g, balance sedikit head-light.', 'Termasuk cover raket Soslay edisi terbatas.']::text[], 'Graphite 100% dengan grommet anti-getar. Senar belum terpasang.', 'active', false, false, 2),
  ('6fc9daa5-193b-41d5-a28c-61811e4376a1', 'court-racket-lite', 'SOS-RCK-005', 'Court Racket Lite', 'racket', 300000, null, 'Raket ringan untuk pemula — mudah diayun, memaafkan pukulan yang belum tepat di tengah.', array['Head size 100 sq in — sweet spot luas, cocok untuk rally panjang.', 'Berat tanpa senar ±300 g, balance sedikit head-light.', 'Termasuk cover raket Soslay edisi terbatas.']::text[], 'Graphite composite. Termasuk senar terpasang (tension 52 lbs).', 'active', false, false, 3),
  ('a78f0afc-82d9-4ca6-a691-c02261623e30', 'blade-green-edition', 'SOS-RCK-007', 'Blade Green Edition', 'racket', 950000, null, 'Edisi hijau untuk yang suka main dengan feel klasik. Fleksibel, presisi, dan jelas mencuri perhatian.', array['Head size 100 sq in — sweet spot luas, cocok untuk rally panjang.', 'Berat tanpa senar ±300 g, balance sedikit head-light.', 'Termasuk cover raket Soslay edisi terbatas.']::text[], 'Braided graphite + basalt. Senar belum terpasang.', 'active', false, false, 4),
  ('e3c8c790-c1e2-4f68-a3af-83d6fdaf076b', 'green-line-racket', 'SOS-RCK-006', 'Green Line Racket', 'racket', 650000, null, 'Raket all-round dengan aksen hijau. Restock berikutnya diumumkan di Instagram kami.', array['Head size 100 sq in — sweet spot luas, cocok untuk rally panjang.', 'Berat tanpa senar ±300 g, balance sedikit head-light.', 'Termasuk cover raket Soslay edisi terbatas.']::text[], 'Graphite composite. Senar belum terpasang.', 'active', false, false, 5);
