insert into content_sections (page, key, label, draft, published, is_enabled, sort_order, published_at) values
  ('home', 'hero', 'Hero', '{"title":"SOSLAY","description":"Bukan sekadar komunitas bermain tenis. Tapi sebuah komunitas untuk bermain, terhubung, dan menikmati momen bersama orang-orang yang tepat","cta":{"label":"Gabung Komunitas","href":"/daftar"},"image":"/images/home/hero.webp","overlay":true}'::jsonb, '{"title":"SOSLAY","description":"Bukan sekadar komunitas bermain tenis. Tapi sebuah komunitas untuk bermain, terhubung, dan menikmati momen bersama orang-orang yang tepat","cta":{"label":"Gabung Komunitas","href":"/daftar"},"image":"/images/home/hero.webp","overlay":true}'::jsonb, true, 0, '2026-09-24T03:24:00.000Z'),
  ('home', 'activities', 'Lebih dari Sekadar Pertandingan', '{"title":"Lebih dari Sekadar Pertandingan!","description":"Dari mabar santai sampai match day, selalu ada cara untuk ikut bermain, bertemu orang baru, dan menikmati serunya tenis bersama komunitas.","cta":{"label":"Booking Session di Kuyy","href":"https://kuy.id/soslay"},"image":null,"overlay":null}'::jsonb, '{"title":"Lebih dari Sekadar Pertandingan!","description":"Dari mabar santai sampai match day, selalu ada cara untuk ikut bermain, bertemu orang baru, dan menikmati serunya tenis bersama komunitas.","cta":{"label":"Booking Session di Kuyy","href":"https://kuy.id/soslay"},"image":null,"overlay":null}'::jsonb, true, 1, '2026-09-24T03:24:00.000Z'),
  ('home', 'stats', 'Statistik', '{"title":"Statistik","description":"500+ Active Members\n60+ Events Hosted\n5+ Sessions per Week\n100% Pro Photography","cta":null,"image":null,"overlay":null}'::jsonb, '{"title":"Statistik","description":"500+ Active Members\n60+ Events Hosted\n5+ Sessions per Week\n100% Pro Photography","cta":null,"image":null,"overlay":null}'::jsonb, true, 2, '2026-09-24T03:24:00.000Z'),
  ('home', 'venues', 'Venue pilihan', '{"title":"Kami Hanya Bermain di Tempat yang Terlihat Bagus.","description":"Kami memilih venue dengan suasana, fasilitas, dan pengalaman yang layak untuk dinikmati. Dari Jakarta sampai Bali, temukan tempat bermain yang bikin setiap sesi terasa lebih spesial.","cta":{"label":"See all Court","href":"/venue"},"image":null,"overlay":null}'::jsonb, '{"title":"Kami Hanya Bermain di Tempat yang Terlihat Bagus.","description":"Kami memilih venue dengan suasana, fasilitas, dan pengalaman yang layak untuk dinikmati. Dari Jakarta sampai Bali, temukan tempat bermain yang bikin setiap sesi terasa lebih spesial.","cta":{"label":"See all Court","href":"/venue"},"image":null,"overlay":null}'::jsonb, true, 3, '2026-09-24T03:24:00.000Z'),
  ('home', 'community', 'The People Make the Game', '{"title":"The People Make the Game.","description":"Temukan komunitas yang membuat setiap permainan terasa lebih berarti. Kenalan, bermain, berbagi momen, dan tumbuh bersama orang-orang yang tepat.","cta":{"label":"Gabung ke Komunitas","href":"/daftar"},"image":null,"overlay":null}'::jsonb, '{"title":"The People Make the Game.","description":"Temukan komunitas yang membuat setiap permainan terasa lebih berarti. Kenalan, bermain, berbagi momen, dan tumbuh bersama orang-orang yang tepat.","cta":{"label":"Gabung ke Komunitas","href":"/daftar"},"image":null,"overlay":null}'::jsonb, true, 4, '2026-09-24T03:24:00.000Z'),
  ('home', 'marquee', 'Marquee', '{"title":"PLAY. CONNECT. REPEAT.","description":"","cta":null,"image":null,"overlay":null}'::jsonb, '{"title":"PLAY. CONNECT. REPEAT.","description":"","cta":null,"image":null,"overlay":null}'::jsonb, true, 5, '2026-09-24T03:24:00.000Z'),
  ('home', 'shop', 'Beyond the Court (Shop)', '{"title":"Beyond the Court.","description":"Koleksi yang terinspirasi dari permainan, perjalanan, dan orang-orang yang membuat setiap momen di SOSLAY terasa spesial.","cta":{"label":"Lihat Koleksi","href":"/shop"},"image":null,"overlay":null}'::jsonb, '{"title":"Beyond the Court.","description":"Koleksi yang terinspirasi dari permainan, perjalanan, dan orang-orang yang membuat setiap momen di SOSLAY terasa spesial.","cta":{"label":"Lihat Koleksi","href":"/shop"},"image":null,"overlay":null}'::jsonb, true, 6, '2026-09-24T03:24:00.000Z'),
  ('home', 'instagram', 'See You on the Court!', '{"title":"See You on the Court!","description":"Lihat keseruan SOSLAY dari dekat. Dari rally seru sampai momen di luar lapangan, semuanya ada di sini.","cta":{"label":"Follow our Instagram","href":"https://instagram.com/socialslay"},"image":null,"overlay":null}'::jsonb, '{"title":"See You on the Court!","description":"Lihat keseruan SOSLAY dari dekat. Dari rally seru sampai momen di luar lapangan, semuanya ada di sini.","cta":{"label":"Follow our Instagram","href":"https://instagram.com/socialslay"},"image":null,"overlay":null}'::jsonb, true, 7, '2026-09-24T03:24:00.000Z'),
  ('home', 'promo', 'Promo banner', '{"title":"Destination Series — drop 10 Oktober","description":"Koleksi baru terinspirasi dari Bali dan Jakarta. Stok terbatas.","cta":{"label":"Lihat koleksi","href":"/shop"},"image":null,"overlay":null}'::jsonb, '{"title":"Destination Series — drop 10 Oktober","description":"Koleksi baru terinspirasi dari Bali dan Jakarta. Stok terbatas.","cta":{"label":"Lihat koleksi","href":"/shop"},"image":null,"overlay":null}'::jsonb, false, 8, '2026-09-24T03:24:00.000Z');
insert into testimonials (author_name, author_handle, quote, avatar_path, is_published, sort_order) values
  ('Anitya Ayu Silfia07', null, 'Niatnya cuma satu sesi. Eh, malah jadi rutin ketemu dan main bareng.', '/images/home/avatar-anitya.webp', true, 0),
  ('vikayusti', '@vikayusti', 'Datang untuk main, tapi selalu ada alasan untuk celebrate bareng.', null, true, 1),
  ('yudisadewa', '@yudisadewa', 'Yang aku suka dari Soslay, semuanya terasa effortless. Datang, main, ketemu orang baru, dan have a good time.', null, true, 2),
  ('sintakusuma', '@sintakusuma', 'Yang bikin ketagihan bukan cuma permainannya, tapi orang-orang yang kamu temui di sepanjang jalan.', null, true, 3),
  ('lily117', '@lily117', 'Main bareng, ketawa bareng, repeat lagi minggu depan.', null, true, 4),
  ('nadiasalsa', '@nadiasalsa', 'Pertama kali ikut Beginner Coaching, coach-nya sabar banget. Sekarang udah berani ikut mabar.', null, false, 5),
  ('gilanghermawan', '@gilanghermawan', 'Tennis Escape ke Bali kemarin jadi trip terbaik tahun ini.', null, false, 6);
